 "content": "def transform(grid):
    # Select the largest non-background object and erode its boundary by one cell.
    from collections import deque
    noise={0,6,7,9}
    seen=set(); objects=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v in noise or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<len(grid) and 0<=xx<len(row) and (yy,xx) not in seen and grid[yy][xx]==v:
                        seen.add((yy,xx)); q.append((yy,xx))
            objects.append((len(cells),v,cells))
    _,color,cells=max(objects)
    S=set(cells)
    core={(r,c) for r,c in S if all((r+dr,c+dc) in S for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))}
    if not core: return [[color]]
    r0=min(r for r,c in core); r1=max(r for r,c in core)
    c0=min(c for r,c in core); c1=max(c for r,c in core)
    return [[color if (r,c) in core else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
